using System.IO;
using System.Text.Json;
using Inferpal.Services.Execution;
using Inferpal.Services.Tools;
using Xunit;

namespace Inferpal.Tests;

// ──────────────────────────────────────────────────────────────────────────────────────────────
//  A file a generator or a designer writes is not edited by hand.
//
//  An edit to InitializeComponent compiles and runs, and the designer can no longer open the form; an edit to an
//  <auto-generated> file is written over at the next build, or the next save of the .resx, the .proto, the model. The
//  three tools that edit a file by hand refuse it before the card, naming where the change belongs; rename_symbol still
//  renames a generated file (it is compiled — left alone, the build breaks) and says the source keeps the old name.
// ──────────────────────────────────────────────────────────────────────────────────────────────
public sealed class GeneratedFilesTests : IDisposable
{
    private readonly string _root = Path.Combine(Path.GetTempPath(), "ip-generated-" + Guid.NewGuid().ToString("N")[..8]);

    public GeneratedFilesTests() => Directory.CreateDirectory(_root);

    public void Dispose()
    {
        try { Directory.Delete(_root, recursive: true); } catch { }
    }

    private string Write(string rel, string text)
    {
        var full = Path.Combine(_root, rel);
        Directory.CreateDirectory(Path.GetDirectoryName(full)!);
        File.WriteAllText(full, text);
        return full;
    }

    private const string Header = "//------------------------------------------------------------------------------\n"
                                + "// <auto-generated>\n//     This code was generated by a tool.\n// </auto-generated>\n"
                                + "//------------------------------------------------------------------------------\n";

    private const string FormDesigner = """
        namespace App
        {
            partial class MainForm
            {
                private System.ComponentModel.IContainer components = null;
                #region Windows Form Designer generated code
                private void InitializeComponent()
                {
                    this.components = new System.ComponentModel.Container();
                }
                #endregion
            }
        }
        """;

    [Fact]
    public void EachKindOfGeneratedFile_NamesWhereTheChangeBelongs()
    {
        Write("MainWindow.xaml", "<Window />");
        Write("Pages/Index.razor", "<h1>Index</h1>");
        Assert.Equal("MainWindow.xaml", GeneratedFiles.Of(Write("obj/Debug/MainWindow.g.cs", Header + "class MainWindow { }"))!.Source);
        Assert.Equal("Index.razor", GeneratedFiles.Of(Write("obj/Pages/Index.razor.g.cs", Header + "class Index { }"))!.Source);
        // A source generator's output has no markup beside it: the remedy names no file that does not exist.
        var generated = GeneratedFiles.Of(Write("obj/Debug/MainViewModel.g.cs", Header + "partial class MainViewModel { }"))!;
        Assert.Null(generated.Source);
        Assert.Contains("source generator", generated.Remedy);
        Write("Properties/Resources.resx", "<root />");
        Assert.Equal("Resources.resx", GeneratedFiles.Of(Write("Properties/Resources.Designer.cs", Header + "class Resources { }"))!.Source);
        Assert.Equal("basket.proto", GeneratedFiles.Of(Write("Protos/Basket.cs", "// <auto-generated>\n//     Generated by the protocol buffer compiler.  DO NOT EDIT!\n//     source: basket.proto\n// </auto-generated>\nclass Basket { }"))!.Source);
        var snapshot = GeneratedFiles.Of(Write("Migrations/ShopContextModelSnapshot.cs",
            "// <auto-generated />\nnamespace App;\npartial class ShopContextModelSnapshot : ModelSnapshot { }"))!;
        Assert.Contains("dotnet ef migrations add", snapshot.Remedy);
        var form = GeneratedFiles.Of(Write("MainForm.Designer.cs", FormDesigner))!;
        Assert.Contains("MainForm.cs", form.Remedy);
        Assert.Contains("generated by", GeneratedFiles.Of(Write("Gen/Thing.cs", Header + "class Thing { }"))!.What + " generated by");
    }

    [Fact]
    public void AnOrdinaryFile_IsNotGenerated()
    {
        // Reference arms: no marker, a Designer.cs that is no designer, a marker in the middle of a large file.
        Assert.Null(GeneratedFiles.Of(Write("Cart.cs", "namespace App; class Cart { }")));
        Assert.Null(GeneratedFiles.Of(Write("Plain.Designer.cs", "namespace App; partial class Plain { }")));
        Assert.Null(GeneratedFiles.Of(Write("Late.cs", "namespace App;\n" + new string(' ', 5000) + "// <auto-generated>\nclass Late { }")));
        // The marker after the first line of code — in a string, in a later comment — is no generated file: a test, an
        // analyzer or a source generator writes it, and must stay editable.
        Assert.Null(GeneratedFiles.Of(Write("Emitter.cs", "namespace App;\nclass Emitter { const string Head = \"// <auto-generated/>\"; }")));
        Assert.Null(GeneratedFiles.Of(Write("Doc.cs", "using System;\n// an <auto-generated> file is written over\nclass Doc { }")));
        // Reference arm: the marker after a license header and #nullable, before the code, is one.
        Assert.NotNull(GeneratedFiles.Of(Write("Gen2.cs", "// Copyright\n#nullable enable\n// <auto-generated/>\nclass Gen2 { }")));
        Assert.Null(GeneratedFiles.Of(Path.Combine(_root, "missing.cs")));
        // A migration's Up/Down file carries the header and is written by hand; its [Migration] lives beside it.
        Assert.Null(GeneratedFiles.Of(Write("Migrations/20261018_Init.cs",
            "// <auto-generated />\nnamespace App;\npublic partial class Init : Migration { protected override void Up(MigrationBuilder b) { } }")));
        Assert.NotNull(GeneratedFiles.Of(Write("Migrations/20261018_Init.Designer.cs",
            "// <auto-generated />\nnamespace App;\n[Migration(\"20261018_Init\")]\npartial class Init { }")));
    }

    private sealed class Spy : IApprovalService
    {
        public int Asked;
        public readonly List<(string Details, bool Forced)> Cards = [];

        public Task<bool> RequestApprovalAsync(string toolName, string details, CancellationToken ct, string? subject = null,
                                               Services.CodeActions.DiffInfo? diff = null, bool forcePrompt = false)
        {
            Asked++;
            Cards.Add((details, forcePrompt));
            return Task.FromResult(true);
        }
    }

    private static async Task<string> Run(ITool tool, object args)
    {
        using var doc = JsonDocument.Parse(JsonSerializer.Serialize(args));
        return await tool.ExecuteAsync(doc.RootElement, CancellationToken.None);
    }

    [Fact]
    public async Task TheThreeToolsThatEditByHand_RefuseAGeneratedFile_BeforeTheCard()
    {
        Write("Properties/Resources.resx", "<root />");
        var resources = Write("Properties/Resources.Designer.cs", Header + "namespace App; class Resources { public static string Hello => \"hi\"; }");
        var spy = new Spy();
        var history = new FileHistoryService();

        var written = await Run(new WriteFileTool(spy, history, () => _root), new { path = resources, content = "class X { }" });
        Assert.Contains("Nothing was written", written);
        Assert.Contains("Resources.resx", written);

        var diffed = await Run(new ApplyDiffTool(spy, history, () => _root),
                               new { path = resources, old_content = "\"hi\"", new_content = "\"hello\"" });
        Assert.Contains("change Resources.resx", diffed);

        var batch = await Run(new ApplyEditsTool(spy, history, () => _root), new
        {
            edits = new object[] { new { path = resources, old_content = "\"hi\"", new_content = "\"hello\"" } },
        });
        Assert.Contains("Nothing was written", batch);

        Assert.Equal(0, spy.Asked);
        Assert.Contains("\"hi\"", File.ReadAllText(resources));
    }

    [Fact]
    public async Task TheDesignersFile_GoesToAForcedCard_ThatWarns()
    {
        // A handler the form no longer has is fixed in InitializeComponent only: the person decides, warned, and no
        // rule or "always" decides for them.
        var form = Write("MainForm.Designer.cs", FormDesigner);
        var spy = new Spy();
        var history = new FileHistoryService();
        var written = await Run(new WriteFileTool(spy, history, () => _root),
                                new { path = form, content = FormDesigner.Replace("partial class MainForm", "partial class MainForm ") });
        Assert.DoesNotContain("Nothing was written", written);
        var edited = await Run(new ApplyEditsTool(spy, history, () => _root), new
        {
            edits = new object[] { new { path = form, old_content = "partial class MainForm ", new_content = "partial class MainForm" } },
        });
        Assert.DoesNotContain("Nothing was written", edited);

        Assert.Equal(2, spy.Asked);
        Assert.All(spy.Cards, c => Assert.True(c.Forced));
        Assert.All(spy.Cards, c => Assert.Contains(Localization.Strings.DesignerFileWarning("MainForm.Designer.cs"), c.Details));
        Assert.Equal(FormDesigner, File.ReadAllText(form));
    }

    [Fact]
    public async Task AnOrdinaryFileBesideThem_StillGoesToTheCard()
    {
        // Reference arm.
        Write("MainForm.Designer.cs", FormDesigner);
        var code = Write("MainForm.cs", "namespace App; partial class MainForm { int x = 1; }");
        var spy = new Spy();
        var edited = await Run(new ApplyDiffTool(spy, new FileHistoryService(), () => _root),
                               new { path = code, old_content = "int x = 1;", new_content = "int x = 2;" });
        Assert.Equal(1, spy.Asked);
        Assert.False(spy.Cards[0].Forced);
        Assert.DoesNotContain("⚠", spy.Cards[0].Details);
        Assert.Contains("int x = 2;", File.ReadAllText(code));
        Assert.DoesNotContain("Nothing was written", edited);
    }

    [Fact]
    public async Task ARenameOfATypeAGeneratedFileUses_RenamesIt_AndSaysItsSourceKeepsTheOldName()
    {
        Write("Properties/Resources.resx", "<root />");
        var resources = Write("Properties/Resources.Designer.cs", Header + "namespace App; class Resources { public static Greeting Make() => new(); }");
        Write("Greeting.cs", "namespace App; public class Greeting { }");
        var spy = new Spy();
        using var doc = JsonDocument.Parse("""{"old_name":"Greeting","new_name":"Salutation","dry_run":false}""");
        var report = await new RenameSymbolTool(spy, new FileHistoryService(), () => _root).ExecuteAsync(doc.RootElement, CancellationToken.None);
        Assert.Contains("Salutation Make()", File.ReadAllText(resources));
        Assert.Contains("is generated from Resources.resx: rename there too", report);
    }

    [Fact]
    public void EveryToolThatRewritesAFile_KnowsGeneratedFiles()
    {
        // A property of the tools: whoever checks the file's encoding before rewriting it (the tools that rewrite a
        // file's content) asks whether a generator writes it.
        var writers = ConventionCoverageTests.ProjectSources("Inferpal.Core")
            .Select(f => (File: Path.GetFileName(f), Code: ConventionCoverageTests.CodeOnly(f)))
            .Where(s => s.Code.Contains("FileTarget.EncodingRefusal(", StringComparison.Ordinal))
            .ToList();
        Assert.True(writers.Count >= 4, $"the scan found {writers.Count} rewriting tools: it reads nothing any more");   // WITNESS
        // Exempt by name: update_memory writes .inferpal/memory.md only, which no generator writes.
        Assert.Empty(writers.Where(s => !s.Code.Contains("GeneratedFiles.", StringComparison.Ordinal)
                                        && s.File != "UpdateMemoryTool.cs")
                            .Select(s => s.File));
    }
}
